import "reflect-metadata";
import { injectable } from "tsyringe";
import { RunAiToolUseCase, RunAiToolInput } from "../../application/use-cases/RunAiToolUseCase";
import { GetAgentsUseCase } from "../../application/use-cases/GetAgentsUseCase";
import { GetAgentByIdUseCase } from "../../application/use-cases/GetAgentByIdUseCase";
import { SaveAgentUseCase } from "../../application/use-cases/SaveAgentUseCase";
import { DeleteAgentUseCase } from "../../application/use-cases/DeleteAgentUseCase";

@injectable()
export class AiController {
    constructor(
        private runAiToolUseCase: RunAiToolUseCase,
        private getAgentsUseCase: GetAgentsUseCase,
        private getAgentByIdUseCase: GetAgentByIdUseCase,
        private saveAgentUseCase: SaveAgentUseCase,
        private deleteAgentUseCase: DeleteAgentUseCase
    ) {}

    async runTool<TInput, TOutput>(params: RunAiToolInput<TInput>): Promise<TOutput> {
        return this.runAiToolUseCase.execute<TInput, TOutput>(params);
    }

    async getAgents(filters?: { category?: string, enabledOnly?: boolean }) {
        return this.getAgentsUseCase.execute(filters);
    }

    async getAgentById(id: string) {
        return this.getAgentByIdUseCase.execute(id);
    }

    async saveAgent(id: string, data: any) {
        return this.saveAgentUseCase.execute(id, data);
    }

    async deleteAgent(id: string) {
        return this.deleteAgentUseCase.execute(id);
    }
}

import { handleApiError, createApiResponse, withAuth } from '@/lib/utils/api-utils';
import { z } from 'zod';
import { container } from '@/infrastructure/di/container';
import { AiController } from '@/modules/ai/adapters/controllers/AiController';

const agentUpdateSchema = z.object({
    name: z.string().min(1).optional(),
    description: z.string().optional(),
    category: z.string().optional(),
    prompt: z.string().optional(),
    guidelines: z.array(z.string()).optional(),
    isEnabled: z.boolean().optional(),
    author: z.string().optional(),
    version: z.string().optional(),
});

export const GET = withAuth(async ({ params }) => {
    try {
        const { id } = await params;
        const controller = container.resolve(AiController);
        const agent = await controller.getAgentById(id);

        if (!agent) {
            return handleApiError({ message: 'Agent not found' }, 404);
        }
        return createApiResponse(agent, 200);
    } catch (error) {
        return handleApiError(error);
    }
});

export const PUT = withAuth(async ({ request, params }) => {
    try {
        const { id } = await params;
        const body = await request.json();
        const validation = agentUpdateSchema.safeParse(body);

        if (!validation.success) {
            return handleApiError(validation.error);
        }

        const controller = container.resolve(AiController);
        const updatedAgent = await controller.saveAgent(id, validation.data);

        return createApiResponse(updatedAgent, 200);
    } catch (error) {
        return handleApiError(error);
    }
}, { requireAdmin: true });

export const DELETE = withAuth(async ({ params }) => {
    try {
        const { id } = await params;
        const controller = container.resolve(AiController);
        await controller.deleteAgent(id);

        return createApiResponse({ message: 'Agent deleted successfully' }, 200);
    } catch (error) {
        return handleApiError(error);
    }
}, { requireAdmin: true });

export interface Feature {
    id: string;
    name: string;
    description: string;
    isEnabled: boolean;
    category?: string;
    updatedAt?: string;
}

import { Feature } from "../entities/Feature";

export interface IFeatureRepository {
    getAll(): Promise<Feature[]>;
    getById(id: string): Promise<Feature | null>;
    update(id: string, data: Partial<Feature>): Promise<Feature>;
}

export const IFeatureRepositoryToken = Symbol("IFeatureRepository");

import { injectable } from "tsyringe";
import { adminDb } from "@/lib/firebase/server-init";
import { IFeatureRepository } from "../../domain/repositories/IFeatureRepository";
import { Feature } from "../../domain/entities/Feature";

@injectable()
export class FirebaseFeatureRepository implements IFeatureRepository {
    private readonly collection = adminDb.collection("features");

    async getAll(): Promise<Feature[]> {
        const snapshot = await this.collection.get();
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Feature));
    }

    async getById(id: string): Promise<Feature | null> {
        const doc = await this.collection.doc(id).get();
        if (!doc.exists) return null;
        return { id: doc.id, ...doc.data() } as Feature;
    }

    async update(id: string, data: Partial<Feature>): Promise<Feature> {
        const ref = this.collection.doc(id);
        const now = new Date().toISOString();
        const dataToUpdate = {
            ...data,
            updatedAt: now
        };
        await ref.update(dataToUpdate);
        const updated = await ref.get();
        return { id: updated.id, ...updated.data() } as Feature;
    }
}

