   2  * 
   3  * This module provides the main RAG functionality: retrieving relevant context
   4  * from the vector store based on a query.
   5  */
   6 
   7 import { generateEmbedding } from './embeddings';
   8 import { getVectorStore, type SearchResult } from './vector-store';
   9 
  10 export interface RetrievalOptions {
  11   topK?: number;
  12   minScore?: number;
  13   projectId?: string;
  14   userId?: string;
  15   includeTypes?: Array<'report' | 'reference' | 'context' | 'user_upload'>;
  16   useCache?: boolean;
  17   rerank?: boolean;
  18   rerankStrategy?: 'cross-encoder' | 'bm25' | 'hybrid' | 'reciprocal-rank-fusion';
  19 }
  20 
  21 export interface RetrievalResult {
  22   context: string;
  23   sources: Array<{
  24     content: string;
  25     score: number;
  26     sourceFile?: string;
  27     type: string;
  28   }>;
  29 }
  30 
  31 /**
  32  * Retrieve relevant context for a query using RAG
  33  */
  34 export async function retrieveContext(
  35   query: string,
  36   options: RetrievalOptions = {}
  37 ): Promise<RetrievalResult> {
  38   const {
  39     topK = 5,
  40     minScore = 0.5,
  41     projectId,
  42     userId,
  43     includeTypes,
  44   } = options;
  45 
  46   try {
  47     const { useCache = true, rerank = false, rerankStrategy = 'hybrid' } = options;
  48 
  49     // Check cache first
  50     if (useCache) {
  51       const { getCacheManager } = await import('./cache');
  52       const cache = getCacheManager().getSearchCache();
  53       const cached = cache.getResults(query, { projectId, topK, minScore });
  54       
  55       if (cached) {
  56         return cached;
  57       }
  58     }
  59 
  60     // 1. Generate embedding for the query (with caching)
  61     const queryEmbedding = await generateEmbedding(query, useCache);
  62 
  63     // 2. Search vector store for similar chunks
  64     const vectorStore = getVectorStore();
  65     
  66     // Load project chunks if projectId is provided
  67     if (projectId) {
  68       await vectorStore.loadProjectChunks(projectId);
  69     }
  70 
  71     let searchResults = await vectorStore.search(queryEmbedding, {
  72       topK: rerank ? topK * 2 : topK, // Get more results if reranking
  73       minScore,
  74       filter: {
  75         projectId,
  76         userId,
  77         type: includeTypes?.[0], // Simple filter for now
  78       },
  79     });
  80 
  81     // 2.5. Apply reranking if enabled
  82     if (rerank && searchResults.length > 0) {
  83       const { getReranker } = await import('./reranker');
  84       const reranker = getReranker();
  85       searchResults = await reranker.rerank(query, searchResults, {
  86         strategy: rerankStrategy,
  87         topK,
  88       });
  89     }
  90 
  91     // 3. Format results
  92     const sources = searchResults.map((result: any) => ({
  93       content: result.chunk.content,
  94       score: result.score,
  95       sourceFile: result.chunk.metadata.sourceFile,
  96       type: result.chunk.metadata.type,
  97     }));
  98 
  99     // 4. Combine context from top results
 100     const context = searchResults
 101       .map((result: any, idx: number) => {
 102         const source = result.chunk.metadata.sourceFile || 'Unknown';
 103         return `[Context ${idx + 1}] (Relevance: ${(result.score * 100).toFixed(1)}%, Source: ${source})\n${result.chunk.content}`;
 104       })
 105       .join('\n\n---\n\n');
 106 
 107     const result = {
 108       context,
 109       sources,
 110     };
 111 
 112     // Cache the result
 113     if (useCache) {
 114       const { getCacheManager } = await import('./cache');
 115       const cache = getCacheManager().getSearchCache();
 116       cache.setResults(query, { projectId, topK, minScore }, result);
 117     }
 118 
 119     return result;
 120   } catch (error) {
 121     console.error('Error retrieving context:', error);
 122     
 123     // Return empty context on error instead of failing
 124     return {
 125       context: '',
 126       sources: [],
 127     };
 128   }
 129 }
 130 
 131 /**
 132  * Retrieve context for multiple queries (batch processing)
 133  */
 134 export async function retrieveContextBatch(
 135   queries: string[],
 136   options: RetrievalOptions = {}
 137 ): Promise<RetrievalResult[]> {
 138   return Promise.all(
 139     queries.map(query => retrieveContext(query, options))
 140   );
 141 }
 142 
 143 /**
 144  * Enhanced retrieval with query expansion
 145  * Generates multiple variations of the query to improve recall
 146  */
 147 export async function retrieveContextEnhanced(
 148   query: string,
 149   options: RetrievalOptions = {}
 150 ): Promise<RetrievalResult> {
 151   // Generate query variations
 152   const queries = [
 153     query,
 154     // Add simple variations
 155     `What is ${query}?`,
 156     `Explain ${query}`,
 157   ];
 158 
 159   // Retrieve for all variations
 160   const results = await retrieveContextBatch(queries, {
 161     ...options,
 162     topK: Math.ceil((options.topK || 5) / queries.length),
 163   });
 164 
 165   // Merge and deduplicate results
 166   const allSources = results.flatMap(r => r.sources);
 167   const uniqueSources = Array.from(
 168     new Map(allSources.map(s => [s.content, s])).values()
 169   )
 170     .sort((a, b) => b.score - a.score)
 171     .slice(0, options.topK || 5);
 172 
 173   const context = uniqueSources
 174     .map((source, idx) => {
 175       return `[Context ${idx + 1}] (Relevance: ${(source.score * 100).toFixed(1)}%, Source: ${source.sourceFile || 'Unknown'})\n${source.content}`;
 176     })
 177     .join('\n\n---\n\n');
 178 
 179   return {
 180     context,
 181     sources: uniqueSources,
 182   };
 183 }
