    type?: 'report' | 'reference' | 'context' | 'user_upload';
    chunkSize?: number;
    overlap?: number;
}

export interface RagRetrievalOptions {
    topK?: number;
    minScore?: number;
    projectId?: string;
    userId?: string;
    includeTypes?: Array<'report' | 'reference' | 'context' | 'user_upload'>;
    useCache?: boolean;
    rerank?: boolean;
    rerankStrategy?: 'cross-encoder' | 'bm25' | 'hybrid' | 'reciprocal-rank-fusion';
}

export interface RagIndexingResult {
    success: boolean;
    chunksCreated: number;
    errors?: string[];
}

export interface RagRetrievalResult {
    context: string;
    sources: Array<{
        content: string;
        score: number;
        sourceFile?: string;
        type: string;
    }>;
}

export interface IRagRepository {
    indexDocument(content: string, options?: RagIndexingOptions): Promise<RagIndexingResult>;
    retrieveContext(query: string, options?: RagRetrievalOptions): Promise<RagRetrievalResult>;
    getStats(): Promise<{ totalChunks: number }>;
    clear(): Promise<void>;
}

export const IRagRepositoryToken = Symbol("IRagRepository");

import "reflect-metadata";
import { injectable } from "tsyringe";
import { IRagRepository, RagIndexingOptions, RagRetrievalOptions, RagIndexingResult, RagRetrievalResult } from "../../domain/repositories/IRagRepository";
import { indexDocument } from "@/lib/rag/indexer";
import { retrieveContext } from "@/lib/rag/retrieval";
import { getVectorStore } from "@/lib/rag/vector-store";

@injectable()
export class DefaultRagRepository implements IRagRepository {
    async indexDocument(content: string, options?: RagIndexingOptions): Promise<RagIndexingResult> {
        const result = await indexDocument(content, options as any);
        return {
            success: result.success,
            chunksCreated: result.chunksCreated,
            errors: result.errors
        };
    }

    async retrieveContext(query: string, options?: RagRetrievalOptions): Promise<RagRetrievalResult> {
        const result = await retrieveContext(query, options as any);
        return {
            sources: result.sources,
            context: result.context
        };
    }

    async getStats(): Promise<{ totalChunks: number }> {
        const vectorStore = getVectorStore();
        let totalChunks = 0;
        if (typeof vectorStore.size === 'function') {
            totalChunks = await vectorStore.size();
        } else {
            totalChunks = vectorStore.size();
        }
        return {
            totalChunks,
        };
    }

    async clear(): Promise<void> {
        const vectorStore = getVectorStore();
        vectorStore.clear();
    }
}

